import java.util.*;
import java.util.function.Predicate;
import java.util.stream.Collectors;

public class FactionMenu extends AbstractInventoryContainer implements ITaskMenu {

    private final IFactionPlayer<?> factionPlayer;
    @Nullable
    private final IRefinementHandler refinementHandler;
    private final TextColor factionColor;
    private final NonNullList<ItemStack> refinementStacks;
    public @NotNull Map<UUID, TaskManager.TaskWrapper> taskWrappers = new HashMap<>();
    public @NotNull Map<UUID, Set<UUID>> completableTasks = new HashMap<>();
    public @NotNull Map<UUID, Map<UUID, Map<Identifier, Integer>>> completedRequirements = new HashMap<>();
    private @Nullable Runnable listener;
    private final boolean refinementsAvailable;
    private final Registry<Task> registry;

    public FactionMenu(int id, @NotNull Inventory inventory) {
        super(FactionMenus.FACTION_MENU.get(), id, inventory, ContainerLevelAccess.NULL, createSlotDefinitions(inventory.player));
        var factionPlayerHandler = FactionPlayerHandler.get(inventory.player);
        this.factionPlayer = factionPlayerHandler.factionPlayer();
        this.factionColor = factionPlayer.getFaction().components().get(FactionDataComponents.CHAT_COLOR.get());
        this.refinementsAvailable = factionPlayer.getFaction().value().hasRefinements();
        this.addPlayerInventorySlots(inventory, 37, 124);
        this.refinementHandler = factionPlayerHandler.getRefinementHandler().asHandler().orElse(null);
        this.refinementStacks = this.refinementHandler != null ? this.refinementHandler.getRefinementItems() : NonNullList.create();
        this.registry = inventory.player.level().registryAccess().lookupOrThrow(FactionRegistries.Keys.TASK);
    }

    private static List<SlotDefinition> createSlotDefinitions(Player player) {
        Holder<? extends IPlayableFaction<?>> faction = FactionPlayerHandler.get(player).getFaction();
        if (IFaction.isNeutral(faction)) throw new IllegalStateException("Cannot open menu without faction");
        if (!faction.value().hasRefinements()) return List.of();

        Predicate<ItemStack> refinement = stack -> stack.getItem() instanceof IRefinementItem item && IFaction.contains(item.getExclusiveFactions(stack), faction);

        return List.of(
                new SlotDefinition(refinement.and(stack -> ((IRefinementItem)stack.getItem()).getSlotType() == IRefinementItem.AccessorySlotType.AMULET), 58, 8),
                new SlotDefinition(refinement.and(stack -> ((IRefinementItem)stack.getItem()).getSlotType() == IRefinementItem.AccessorySlotType.RING), 58, 26),
                new SlotDefinition(refinement.and(stack -> ((IRefinementItem)stack.getItem()).getSlotType() == IRefinementItem.AccessorySlotType.OBI_BELT), 58, 44)
        );
    }

    @Override
    public boolean showLocateTaskmaster() {
        return true;
    }

    @Override
    public BlockPos getLastKnownPosition(ITaskInstance instance) {
        var taskWrapper = this.taskWrappers.get(instance.getTaskBoard());
        if (taskWrapper != null) {
            return taskWrapper.getLastSeenPos().orElse(null);
        }
        return null;
    }

    @Override
    protected Slot createSlot(Container container, int index, SlotDefinition definition) {
        return new RemovingSelectorSlot(container, index, definition, this::isSlotEnabled);
    }

    @Override
    protected void onInputSlotChanged(Container container) {
        super.onInputSlotChanged(container);
        if (this.refinementHandler != null) {
            refinementHandler.updateItems();
        }
    }

    @Override
    protected Container createInputContainer(int size) {
        return new RefinementContainer();
    }

    @Override
    public Registry<Task> getRegistry() {
        return this.registry;
    }

    @Override
    public boolean areRequirementsCompleted(@NotNull ITaskInstance taskInfo, @NotNull TaskRequirement.Type type) {
        if (this.completedRequirements.containsKey(taskInfo.getTaskBoard()) && this.completedRequirements.get(taskInfo.getTaskBoard()).containsKey(taskInfo.getId())) {
            Map<Identifier, Integer> data = this.completedRequirements.get(taskInfo.getTaskBoard()).get(taskInfo.getId());
            for (TaskRequirement.Requirement<?> requirement : getTask(taskInfo.getTask()).requirements().requirements().get(type)) {
                if (!data.containsKey(requirement.id()) || data.get(requirement.id()) < requirement.getAmount(this.factionPlayer)) {
                    return false;
                }
            }
            return true;
        }
        return false;
    }

    @Override
    public @NotNull TaskAction buttonAction(@NotNull ITaskInstance taskInfo) {
        return taskInfo.isUnique(this.registry) || this.factionPlayer.asEntity().level().getGameTime() < taskInfo.getTaskTimeStamp() ? TaskAction.ABORT : TaskAction.REMOVE;
    }

    @Override
    public boolean canCompleteTask(@NotNull ITaskInstance taskInfo) {
        return this.completableTasks.containsKey(taskInfo.getTaskBoard()) && this.completableTasks.get(taskInfo.getTaskBoard()).contains(taskInfo.getId()) && (taskInfo.isUnique(this.registry) || this.factionPlayer.asEntity().level().getGameTime() < taskInfo.getTaskTimeStamp());
    }

    @Override
    public TextColor getFactionColor() {
        return this.factionColor;
    }

    public NonNullList<ItemStack> getRefinementStacks() {
        return refinementStacks;
    }

    @Override
    protected boolean isSlotEnabled(int id) {
        return refinementsAvailable;
    }

    public boolean areRefinementsAvailable() {
        return refinementsAvailable;
    }

    @Override
    public int getRequirementStatus(@NotNull ITaskInstance taskInfo, @NotNull TaskRequirement.Requirement<?> requirement) {
        if (this.completedRequirements.containsKey(taskInfo.getTaskBoard())) {
            return this.completedRequirements.get(taskInfo.getTaskBoard()).get(taskInfo.getId()).get(requirement.id());
        } else {
            return requirement.getAmount(this.factionPlayer);
        }
    }

    public @NotNull Collection<ITaskInstance> getTaskInfos() {
        return this.taskWrappers.values().stream().flatMap(t -> t.getTaskInstances().stream().filter(ITaskInstance::isAccepted)).collect(Collectors.toList());
    }

    public void init(@NotNull Map<UUID, TaskManager.TaskWrapper> taskWrapper, @NotNull Map<UUID, Set<UUID>> completableTasks, @NotNull Map<UUID, Map<UUID, Map<Identifier, Integer>>> completedRequirements) {
        this.taskWrappers = taskWrapper;
        this.completedRequirements = completedRequirements;
        this.completableTasks = completableTasks;
        if (this.listener != null) {
            this.listener.run();
        }
    }

    @Override
    public boolean isCompleted(@NotNull ITaskInstance item) {
        return false;
    }

    @Override
    public boolean isRequirementCompleted(@NotNull ITaskInstance taskInfo, @NotNull TaskRequirement.Requirement<?> requirement) {
        if (this.completedRequirements.containsKey(taskInfo.getTaskBoard()) && this.completedRequirements.get(taskInfo.getTaskBoard()).containsKey(taskInfo.getId())) {
            Map<Identifier, Integer> data = this.completedRequirements.get(taskInfo.getTaskBoard()).get(taskInfo.getId());
            return data.containsKey(requirement.id()) && data.get(requirement.id()) >= requirement.getAmount(this.factionPlayer);
        }
        return false;
    }

    @Override
    public boolean isTaskNotAccepted(@NotNull ITaskInstance taskInfo) {
        return false;
    }

    @Override
    public void pressButton(@NotNull ITaskInstance taskInfo) {
        FactionsMod.proxy.sendToServer(new ServerboundTaskActionPacket(taskInfo.getId(), taskInfo.getTaskBoard(), buttonAction(taskInfo)));
        this.taskWrappers.get(taskInfo.getTaskBoard()).removeTask(taskInfo, true);
        if (this.listener != null) {
            this.listener.run();
        }
    }

    @Override
    public void setReloadListener(@Nullable Runnable listener) {
        this.listener = listener;
    }

    public static class RemovingSelectorSlot extends InputSlot {

        public RemovingSelectorSlot(Container container, int index, SlotDefinition definition, Predicate<Integer> activeCheck) {
            super(container, index, definition, activeCheck);
        }

        @Override
        public void set(@NotNull ItemStack stack) {
            if (!stack.isEmpty()) {
                this.container.setItem(this.getSlotIndex(), stack);
            }
        }

        @Override
        public boolean mayPickup(@NotNull Player player) {
            return false;
        }
    }

    private class RefinementContainer implements Container {

        @Override
        public int getContainerSize() {
            return refinementStacks.size();
        }

        @Override
        public boolean isEmpty() {
            return refinementStacks.isEmpty();
        }

        @Override
        public @NotNull ItemStack getItem(int slot) {
                return refinementStacks.get(slot);
        }

        @Override
        public @NotNull ItemStack removeItem(int slot, int amount) {
            return refinementStacks.remove(slot);
        }

        @Override
        public @NotNull ItemStack removeItemNoUpdate(int slot) {
                return refinementStacks.remove(slot);
        }

        @Override
        public void setItem(int slot, @NotNull ItemStack stack) {
            refinementStacks.set(slot, stack);
        }

        @Override
        public void setChanged() {
            FactionMenu.this.slotsChanged(this);
        }

        @Override
        public boolean stillValid(@NotNull Player player) {
            return true;
        }

        @Override
        public void clearContent() {
        }
    }

}

package de.teamlapen.sync;

import de.teamlapen.sync.api.ISyncable;
import de.teamlapen.sync.properties.IProperty;
import de.teamlapen.sync.properties.Property;
import net.minecraft.resources.Identifier;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.common.util.ValueIOSerializable;
import org.jetbrains.annotations.ApiStatus;
import org.jetbrains.annotations.MustBeInvokedByOverriders;

import java.util.*;

/**
 * Base class for sync-able properties.
 * <p>
 * Handles registering, syncing ob properties
 * <p>
 * To make use of this class, you need to override {@link #registerProperties()}. In the implementation you can register properties.
 * <p>
 * Properties are registered using {@link #registerProperty(Identifier)}.
 * <p>
 * To handle property changes, override {@link #onPropertyChanged()}.
 */
public abstract class PropertySync implements ValueIOSerializable, ISyncable, IProperty {

    private final Map<Identifier, Property> propertiesMap = new HashMap<>();
    protected final Collection<Property> properties = Collections.unmodifiableCollection(propertiesMap.values());

    public PropertySync() {
        this.registerProperties();
    }

    /**
     * This method is called in the constructor of this class.
     * It should be used to register properties using {@link #registerProperty(Identifier)}
     */
    @ApiStatus.OverrideOnly
    protected void registerProperties() {

    }

    //<editor-fold desc="IProperty">

    @Override
    public int getStatus() {
        return Objects.hash(this.properties.stream().map(Property::getStatus).toList());
    }

    @Override
    public boolean hasClientSync() {
        return this.properties.stream().anyMatch(Property::hasClientSync);
    }

    @Override
    public boolean hasServerLoad() {
        return this.properties.stream().anyMatch(Property::hasServerLoad);
    }

    //</editor-fold>

    //<editor-fold desc="Properties">

    @ApiStatus.OverrideOnly
    protected void onPropertyChanged() {

    }

    public final void registerProperty(Property property) {
        this.propertiesMap.put(property.key(), property);
    }

    protected final Property.PropertyBuilder registerProperty(Identifier key) {
        return new Property.PropertyBuilder(this, key);
    }

    //</editor-fold>

    //<editor-fold desc="Serialization">

    @Override
    @MustBeInvokedByOverriders
    public void serialize(ValueOutput output) {
        for (Property syncProperty : this.properties) {
            if (syncProperty.hasServerLoad()) {
                syncProperty.storeValue(output, Property.StoreMode.FULL);
            }
        }
    }

    @Override
    @MustBeInvokedByOverriders
    public void deserialize(ValueInput input) {
        for (Property syncProperty : this.properties) {
            if (!syncProperty.hasServerLoad()) continue;
            syncProperty.loadServer(input);
        }

        onPropertyChanged();
    }

    @Override
    public final void serializeFullUpdate(ValueOutput output) {
        for (Property property : this.properties) {
            if (property.hasClientSync()) {
                property.store(output, Property.StoreMode.FULL_UPDATE);
            }
        }
    }

    @Override
    public final void serializeUpdate(ValueOutput output) {
        for (Property property : this.properties) {
            if (property.hasClientSync() && property.hasChanged()) {
                property.store(output, Property.StoreMode.UPDATE);
            }
        }
    }

    @Override
    public final boolean deserializeUpdate(ValueInput input) {
        boolean changed = false;
        for (Property property : this.properties) {
            if (property.hasClientSync()) {
                changed = property.loadClient(input) || changed;
            }
        }

        if (changed) {
            onPropertyChanged();
            return true;
        }
        return false;
    }

    //</editor-fold>
}

package de.teamlapen.sync.properties;

import com.google.common.base.Preconditions;
import com.mojang.serialization.Codec;
import net.minecraft.resources.Identifier;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import org.jetbrains.annotations.Nullable;

import java.util.Comparator;
import java.util.Optional;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Supplier;

public class SimpleProperty<T> extends Property {

    private final Codec<T> codec;
    private final Supplier<T> defaultValue;
    private final Supplier<T> valueProvider;
    private final DataApply<T> valueSetter;

    public SimpleProperty(Identifier key, Codec<T> codec, Supplier<T> defaultValue, Supplier<T> valueProvider, DataApply<T> valueSetter) {
        super(key);
        this.codec = codec;
        this.defaultValue = defaultValue;
        this.valueProvider = valueProvider;
        this.valueSetter = valueSetter;
    }

    @Override
    public boolean hasClientSync() {
        return this.valueSetter.canLoadClient();
    }

    @Override
    public boolean hasServerLoad() {
        return this.valueSetter.canLoadServer();
    }

    @Override
    public int getStatus() {
        return this.valueProvider.get().hashCode();
    }

    public int storeValue(ValueOutput output, StoreMode mode) {
        T t = this.valueProvider.get();
        output.store(this.key.toString(), this.codec, t);

        return t.hashCode();
    }

    public boolean loadClient(ValueInput input) {
        if (!this.valueSetter.canLoadClient()) return false;

        return input.read(this.key.toString(), this.codec).map(valueSetter::loadClient).orElse(false);
    }

    public void loadServer(ValueInput input) {
        if (!this.valueSetter.canLoadServer()) return;

        var value = input.read(this.key.toString(), this.codec).orElseGet(this.defaultValue);
        this.valueSetter.loadServer(value);
    }

    public static class Builder<T> {

        private final PropertyBuilder baseBuilder;
        private final Codec<T> codec;
        @Nullable
        private Supplier<T> defaultValue;
        @Nullable
        private Supplier<T> supplier;
        @Nullable
        private Consumer<T> serverLoader;
        @Nullable
        private Function<T, Boolean> clientLoader;
        @Nullable
        private Consumer<T> clientLoaderSimple;
        @Nullable
        private Comparator<T> comparator;

        public Builder(PropertyBuilder baseBuilder, Codec<T> codec) {
            this.baseBuilder = baseBuilder;
            this.codec = codec;
        }

        public Builder<T> defaultValue(T defaultValue) {
            this.defaultValue = () -> defaultValue;
            return this;
        }

        public Builder<T> defaultValue(Supplier<T> defaultValue) {
            this.defaultValue = defaultValue;
            return this;
        }

        public Builder<T> provider(Supplier<T> supplier) {
            this.supplier = supplier;
            return this;
        }

        public Builder<T> serverLoader(Consumer<T> loader) {
            this.serverLoader = loader;
            return this;
        }

        public Builder<T> clientLoader(Function<T, Boolean> loader) {
            this.clientLoader = loader;
            return this;
        }

        public Builder<T> commonLoader(Function<T, Boolean> loader) {
            this.serverLoader = loader::apply;
            this.clientLoader = loader;
            return this;
        }

        public Builder<T> commonLoader(Consumer<T> loader, Comparator<T> comparator) {
            this.serverLoader = loader;
            this.clientLoaderSimple = loader;
            this.comparator = comparator;
            return this;
        }

        public Builder<T> comparator(Comparator<T> comparator) {
            this.comparator = comparator;
            return this;
        }

        public void register() {
            Preconditions.checkArgument( this.defaultValue != null, "Default value must be set");
            Preconditions.checkArgument( this.supplier != null, "Supplier must be set");
            Preconditions.checkArgument( this.serverLoader != null ||  this.clientLoader != null, "Server or client loaders must be set");
            Preconditions.checkArgument(this.clientLoaderSimple == null || this.clientLoader == null, "Only one of clientLoader or clientLoaderSimple can be set");
            Preconditions.checkArgument(this.clientLoader != null || (this.clientLoaderSimple == null || this.comparator != null), "Comparator must be set if clientLoaderSimple is set");

            if (this.clientLoader != null && this.comparator != null) {
                this.clientLoader = value -> {
                    assert this.supplier != null;
                    assert this.clientLoader != null;
                    assert comparator != null;

                    T t = this.supplier.get();
                    this.clientLoader.apply(value);
                    return comparator.compare(t, value) != 0;
                };
            }

            if (this.clientLoaderSimple != null) {
                this.clientLoader = value -> {
                    assert this.supplier != null;
                    assert this.clientLoaderSimple != null;
                    assert comparator != null;

                    T t = this.supplier.get();
                    this.clientLoaderSimple.accept(value);
                    return comparator.compare(t, value) != 0;
                };
            }

            this.baseBuilder.register(key -> {
                assert this.defaultValue != null;
                assert this.supplier != null;
                return new SimpleProperty<>(key, this.codec, this.defaultValue, this.supplier, DataApply.create(serverLoader, clientLoader));
            });
        }


    }

    public static class NullableBuilder<T> {

        private final Builder<Optional<T>> innerBuilder;

        public NullableBuilder(PropertyBuilder baseBuilder, Codec<@Nullable T> codec) {
            this.innerBuilder = new Builder<>(baseBuilder,  Codec.optionalField("value", codec, true).codec()).defaultValue(Optional.empty());
        }

        public NullableBuilder<T> defaultValue(@Nullable T defaultValue) {
            this.innerBuilder.defaultValue(Optional.ofNullable(defaultValue));
            return this;
        }

        public NullableBuilder<T> defaultValue(Supplier<@Nullable T> defaultValue) {
            this.innerBuilder.defaultValue(() -> Optional.ofNullable(defaultValue.get()));
            return this;
        }

        public NullableBuilder<T> provider(Supplier<@Nullable T> supplier) {
            this.innerBuilder.provider(() -> Optional.ofNullable(supplier.get()));
            return this;
        }

        public NullableBuilder<T> serverLoader(Consumer<@Nullable T> loader) {
            this.innerBuilder.serverLoader(x -> loader.accept(x.orElse(null)));
            return this;
        }

        public NullableBuilder<T> clientLoader(Function<@Nullable T, Boolean> loader) {
            this.innerBuilder.clientLoader(x -> loader.apply(x.orElse(null)));
            return this;
        }

        public NullableBuilder<T> commonLoader(Function<@Nullable T, Boolean> loader) {
            this.innerBuilder.commonLoader(x -> loader.apply(x.orElse(null)));
            return this;
        }

        public NullableBuilder<T> commonLoader(Consumer<@Nullable T> loader, Comparator<Optional<T>> comparator) {
            this.innerBuilder.commonLoader(x -> loader.accept(x.orElse(null)), comparator);
            return this;
        }

        public NullableBuilder<T> comparator(Comparator<@Nullable T> comparator) {
            this.innerBuilder.comparator(new Comparator<>() {
                private final Comparator<@Nullable T> delegate = comparator;

                @Override
                public int compare(Optional<T> o1, Optional<T> o2) {
                    return delegate.compare(o1.orElse(null), o2.orElse(null));
                }
            });
            return this;
        }

        public void register() {
            this.innerBuilder.register();
        }
    }
